export type Priority="LOW"|"MEDIUM"|"HIGH"|"CRITICAL";
export type Ticket=Readonly<{id:number;title:string;priority:Priority;createdAt:string;assignee:string|null}>;
export type SortKey="id"|"title"|"priority"|"createdAt";
export type Direction="asc"|"desc";
export type SortState=Readonly<{key:SortKey;direction:Direction}>;
export const PRIORITY_RANK:Record<Priority,number>={LOW:0,MEDIUM:1,HIGH:2,CRITICAL:3};
type Comparator=(a:Ticket,b:Ticket)=>number;
const COMPARATORS:Record<SortKey,Comparator>={id:(a,b)=>a.id-b.id,title:(a,b)=>a.title.localeCompare(b.title,"pl"),priority:(a,b)=>PRIORITY_RANK[a.priority]-PRIORITY_RANK[b.priority],createdAt:(a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt)};
export function sortTickets(tickets:readonly Ticket[],sort:SortState):Ticket[]{const sign=sort.direction==="asc"?1:-1;return tickets.toSorted((a,b)=>COMPARATORS[sort.key](a,b)*sign);}
export function nextSort(current:SortState,key:SortKey):SortState{return current.key===key?{key,direction:current.direction==="asc"?"desc":"asc"}:{key,direction:"asc"};}
export function compareNullableText(a:string|null,b:string|null,direction:Direction):number{if(a===null&&b===null)return 0;if(a===null)return 1;if(b===null)return -1;return a.localeCompare(b,"pl")*(direction==="asc"?1:-1);}
